class Solution {
public:
    int countNumbersWithUniqueDigits(int a, int b) {
        int ans = 0;
        for (int x = a; x <= b; x++) {
            int mask = 0, y = x; bool ok = true;
            while (y) { int d = 1 << (y % 10); if (mask & d) { ok = false; break; } mask |= d; y /= 10; }
            ans += ok;
        }
        return ans;
    }
};

