class Solution {
    public int countNumbersWithUniqueDigits(int a, int b) {
        int ans = 0;
        for (int x = a; x <= b; x++) {
            int mask = 0, y = x; boolean ok = true;
            while (y > 0) { int d = 1 << (y % 10); if ((mask & d) != 0) { ok = false; break; } mask |= d; y /= 10; }
            if (ok) ans++;
        }
        return ans;
    }
}

