class Solution:
    def countNumbersWithUniqueDigits(self, a: int, b: int) -> int:
        good = [False] * (b + 1)
        mask = [0] * (b + 1)
        cnt = 0
        for x in range(1, b + 1):
            d = x % 10
            bit = 1 << d
            good[x] = good[x // 10] and not (mask[x // 10] & bit)
            mask[x] = mask[x // 10] | bit
            if a <= x <= b and good[x]:
                cnt += 1
        return cnt

