        vector<char> good(b + 1, 0); vector<int> mask(b + 1, 0);
        int cnt = 0;
        for (int x = 1; x <= b; x++) {
            int bit = 1 << (x % 10);
            good[x] = good[x / 10] && !(mask[x / 10] & bit);
            mask[x] = mask[x / 10] | bit;
            if (x >= a && good[x]) cnt++;
        }
        return cnt;
    }
};

