class Solution {
    public int countNumbersWithUniqueDigits(int a, int b) {
        boolean[] good = new boolean[b + 1]; int[] mask = new int[b + 1];
        int cnt = 0;
        for (int x = 1; x <= b; x++) {
            int bit = 1 << (x % 10);
            good[x] = good[x / 10] && (mask[x / 10] & bit) == 0;
            mask[x] = mask[x / 10] | bit;
            if (x >= a && good[x]) cnt++;
        }
        return cnt;
    }
}

